<script setup lang="ts">
import { ref, watch } from 'vue'

const props = withDefaults(
  defineProps<{
    src?: string
    /** Project name, used as alt text */
    name: string
    size?: number
  }>(),
  { src: '', size: 40 },
)

const failed = ref(false)
watch(
  () => props.src,
  () => {
    failed.value = false
  },
)
</script>

<template>
  <span class="thumb" :style="{ width: `${size}px`, height: `${size}px` }">
    <img
      v-if="src && !failed"
      :src="src"
      :alt="name"
      :title="name"
      loading="lazy"
      @error="failed = true"
    />
    <i v-else class="mdi mdi-image-outline placeholder" role="img" :aria-label="`${name}: no image`"></i>
  </span>
</template>

<style scoped>
.thumb {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: var(--surface-sunken);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
}

.thumb img {
  width: 100%;
  height: 100%;
