import EnoviaApi from "@/api/enoviaApi";
import { getTenant } from "@/config/platformUrls";

const RESOURCES = "/resources";

/** Tenant used when the widget runs outside 3DDashboard (no platform id available). */
const FALLBACK_TENANT = "R1132101701695";

// Fields requested for project details (mirrors the reference curl request exactly).
const PROJECT_FIELDS = [
  "All", "title", "description", "PALId", "sequenceOrder", "state", "policy", "ganttConfig",
  "status", "nlsType", "symbol", "pattern", "color", "modifyAccess", "estimatedStartDate",
  "estimatedFinishDate", "dueDate", "percentComplete", "estimatedDurationInputValue",
  "estimatedDurationInputUnit", "actualDuration", "constraintDate", "defaultConstraintType",
  "scheduleFrom", "scheduleBasedOn", "typeicon", "forecastStartDate", "forecastFinishDate",
  "forecastDuration",
  "tasks.title", "tasks.description", "tasks.nlsType", "tasks.dpmTaskCalendar",
  "tasks.dpmTaskCalendarName", "tasks.modifyAccess", "tasks.restrictAssigneeAccess",
  "tasks.deleteAccess", "tasks.changeSOVAccess", "tasks.isOverallCritical", "tasks.freeFloat",
  "tasks.totalFloat", "tasks.PALId.transient", "tasks.state", "tasks.notes",
  "tasks.percentComplete", "tasks.estimatedStartDate", "tasks.dueDate",
  "tasks.estimatedDurationInputValue", "tasks.estimatedDurationInputUnit",
  "tasks.constraintType", "tasks.Deviation", "tasks.constraintDate", "tasks.policy",
  "tasks.passiveSubtask", "tasks.isSummaryTask", "tasks.symbol", "tasks.pattern", "tasks.color",
  "tasks.isTypeGate", "tasks.isTypeMilestone", "tasks.sourceId", "tasks.taskProjectId",
  "tasks.criticalTask", "tasks.status", "tasks.typeicon", "tasks.sequenceOrder",
  "predecessors.title", "predecessors.PALId", "predecessors.lagTimeInputValue",
  "predecessors.lagTimeInputUnit", "predecessors.dependencyType", "predecessors.LagUnit",
  "predecessors.From", "predecessors.predTaskSeqNumber", "predecessors.To",
  "predecessors.predProjectName", "predecessors.predProjectId",
  "assignees.name", "assignees.fullname", "assignees.firstname", "assignees.lastname",
  "assignees.allocation",
  "ownerInfo.name", "ownerInfo.firstname", "ownerInfo.lastname", "ownerInfo.fullname",
  "tasks.calculateDuration", "tasks.actualStartDate", "tasks.actualFinishDate",
  "tasks.actualDuration", "tasks.taskCompletionType", "tasks.forecastStartDate",
  "tasks.forecastFinishDate", "tasks.forecastDuration", "tasks.Deviation",
].join(",");

class EnoviaService extends EnoviaApi {
  constructor(path, option = {}) {
    super(path, option);
  }

  /** Current user's preferred credentials and collaborative spaces. */
  getCollabspaces() {
    this.path = `${RESOURCES}/modeler/pno/person?current=true&select=preferredcredentials&select=collabspaces`;
    return super.get();
  }

  /**
   * Fetch full project details including tasks/milestones.
   * @param {string} projectId  resourceid from the federated search result
   * @param {string} secCtx     SecurityContext string from Util.getCTX()
   * @param {string} tenant     tenant id (defaults to the current platform id)
   */
  getProjectDetails(projectId, secCtx, tenant = getTenant(FALLBACK_TENANT)) {
    this.path =
      `${RESOURCES}/v1/modeler/projects/${projectId}` +
      `?tenant=${tenant}` +
      `&$simpleJSON=true` +
      `&owned=true` +
      `&$fields=${PROJECT_FIELDS}` +
      `&$include=none,tasks,predecessors,assignees,ownerInfo` +
      `&isDPMTask=true` +
      `&$indexBasedImages=false` +
      `&rollup=live` +
      `&isCustomizedEnvironment=false` +
      `&level=0` +
      `&validateType=true` +
      `&xrequestedwith=xmlhttprequest`;
    // securitycontext is a plain header (not ENO_CSRF_TOKEN).
    this.option = { headers: { securitycontext: secCtx } };
    return super.get();
  }
}

export default EnoviaService;
