import { computed, ref, watch, type Ref } from 'vue'
import type { Milestone } from '@/dashboard/types/project'
import type { FedSearchItem } from './useFederatedSearch'
import {
  itemCollabSpace,
  matchesProjectPrefix,
  type ProjectDetail,
  type useProjectMilestones,
} from './useProjectMilestones'

type ProjectMilestones = ReturnType<typeof useProjectMilestones>

/** Option label for projects whose collaborative space search did not return. */
export const NO_COLLAB_SPACE = 'Not set'

/** Remembers the selection in this browser (per-viewer convenience only). */
const STORAGE_KEY = 'projectTracker.collabSpaces'

export interface CollabSpaceOption {
  name: string
  /** Projects in this collaborative space */
  count: number
}

function loadSelection(): string[] {
  try {
    const parsed: unknown = JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? '[]')
    return Array.isArray(parsed) ? parsed.filter((v): v is string => typeof v === 'string') : []
  } catch {
    return []
  }
}

function saveSelection(selection: string[]) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(selection))
  } catch {
    // Storage unavailable (private mode, blocked): the filter still works for this session.
  }
}

const spaceOf = (name: string) => name || NO_COLLAB_SPACE

/**
 * Multi-select collaborative space filter applied to every tab.
 *
 * Options come from the search results (available before project details load), so the
 * list is complete straight away. An empty selection means "all collaborative spaces".
 * Filtering is client-side: changing it is instant and triggers no new requests.
 */
export function useCollabSpaceFilter(
  searchResults: Ref<FedSearchItem[]>,
  source: ProjectMilestones,
) {
  const selected = ref<string[]>(loadSelection())
  watch(selected, saveSelection, { deep: true })

  const options = computed<CollabSpaceOption[]>(() => {
    const counts = new Map<string, number>()
    for (const item of searchResults.value) {
      if (!matchesProjectPrefix(item)) continue
      const name = spaceOf(itemCollabSpace(item))
      counts.set(name, (counts.get(name) ?? 0) + 1)
    }
    return Array.from(counts, ([name, count]) => ({ name, count })).sort((a, b) =>
      a.name.localeCompare(b.name),
    )
  })

  /**
   * Selected spaces that still exist. A remembered space that no longer has projects is
   * ignored, so a stale selection never hides everything.
   */
  const activeSelection = computed(() => {
    const available = new Set(options.value.map((o) => o.name))
    return selected.value.filter((name) => available.has(name))
  })

  const isAll = computed(() => activeSelection.value.length === 0)

  const projects = computed<ProjectDetail[]>(() => {
    if (isAll.value) return source.projects.value
    const wanted = new Set(activeSelection.value)
    return source.projects.value.filter((p) => wanted.has(spaceOf(p.collabSpace)))
  })

  function onlyVisible(markers: Ref<Record<string, Milestone[]>>) {
    return computed<Record<string, Milestone[]>>(() => {
      if (isAll.value) return markers.value
      return Object.fromEntries(
        projects.value.map((p) => [p.projectId, markers.value[p.projectId] ?? []]),
      )
    })
  }

  /** Same shape as useProjectMilestones(), restricted to the selected spaces. */
  const filteredMilestones: ProjectMilestones = {
    ...source,
    projects: projects as unknown as ProjectMilestones['projects'],
    customerMarkersByProject: onlyVisible(source.customerMarkersByProject) as unknown as
      ProjectMilestones['customerMarkersByProject'],
    indoMarkersByProject: onlyVisible(source.indoMarkersByProject) as unknown as
      ProjectMilestones['indoMarkersByProject'],
  }

  return {
    options,
    selected,
    activeSelection,
    isAll,
    filteredMilestones,
    clear: () => {
      selected.value = []
    },
  }
}
