/** Short month name, e.g. "Aug". */
export function shortMonth(date: Date): string {
  return date.toLocaleString('en-US', { month: 'short' })
}

/** Formats a date as a month label, e.g. "Aug '26". */
export function formatMonthLabel(date: Date): string {
  return `${shortMonth(date)} '${String(date.getFullYear()).slice(2)}`
}

/** Formats a date as a day label, e.g. "11 Aug '26". */
export function formatDayLabel(date: Date): string {
  return `${date.getDate()} ${formatMonthLabel(date)}`
}

/** Parses an API date string; returns null when empty or invalid. */
export function parseApiDate(value: unknown): Date | null {
  if (!value) return null
  const date = new Date(String(value))
  return isNaN(date.getTime()) ? null : date
}

/** Parses a month label ("Aug '26") into the first day of that month, or null. */
export function parseMonthLabel(label: string): Date | null {
  if (!label) return null
  const match = /^(\w+)\s+'(\d{2})$/.exec(label.trim())
  if (!match) return null
  const month = new Date(`${match[1]} 1, 2000`).getMonth()
  const year = 2000 + parseInt(match[2], 10)
  if (isNaN(month) || isNaN(year)) return null
  return new Date(year, month, 1)
}
