import {
  Chart as ChartJS,
  ArcElement,
  BarElement,
  CategoryScale,
  Legend,
  LinearScale,
  LineElement,
  PointElement,
  Title,
  Tooltip,
} from 'chart.js'

let configured = false

/** Registers Chart.js parts and applies the dashboard look. Safe to call more than once. */
export function setupChartTheme() {
  if (configured) return
  configured = true

  ChartJS.register(
    Title,
    Tooltip,
    Legend,
    ArcElement,
    BarElement,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
  )

  ChartJS.defaults.font.family = "'Archivo Variable', 'Segoe UI', system-ui, sans-serif"
  ChartJS.defaults.font.size = 12
  ChartJS.defaults.color = '#5a6b7b'

  const tooltip = ChartJS.defaults.plugins.tooltip
  tooltip.backgroundColor = '#14202b'
  tooltip.titleColor = '#ffffff'
  tooltip.bodyColor = '#dbe1e6'
  tooltip.padding = 10
  tooltip.cornerRadius = 4
  tooltip.boxPadding = 4
}

export const CHART_COLORS = {
  grid: '#e9edf0',
  tick: '#7f8e9c',
  surface: '#ffffff',
  primary: '#2f4b66',
  primaryHover: '#005686',
  muted: '#9aa8b6',
} as const
