<script setup lang="ts">
import { nextTick, ref, provide } from 'vue'
import ProjectsTab from './components/ProjectsTab.vue'
import TimelineTab from './components/TimelineTab.vue'
import EventStatusTab from './components/EventStatusTab.vue'
import CollabSpaceFilter from './components/common/CollabSpaceFilter.vue'
import { useFederatedSearch } from '@/dashboard/composables/useFederatedSearch'
import { useProjectMilestones } from '@/dashboard/composables/useProjectMilestones'
import { useCollabSpaceFilter } from '@/dashboard/composables/useCollabSpaceFilter'
import { COLLAB_FILTER_KEY, FED_SEARCH_KEY, PROJECT_MILESTONES_KEY } from '@/dashboard/injectionKeys'

type TabId = 'projects' | 'timeline' | 'event'

interface TabDefinition {
  id: TabId
  label: string
  icon: string
}

const tabs: TabDefinition[] = [
  { id: 'projects', label: 'Projects', icon: 'mdi-view-dashboard-outline' },
  { id: 'timeline', label: 'Timeline', icon: 'mdi-clock-outline' },
  { id: 'event', label: 'Event Status', icon: 'mdi-format-list-checks' },
]

const activeTab = ref<TabId>('projects')

const fedSearch = useFederatedSearch()
const milestones = useProjectMilestones(fedSearch.results)
const collabFilter = useCollabSpaceFilter(fedSearch.results, milestones)
const { options: collabOptions, selected: collabSelected, activeSelection } = collabFilter

provide(FED_SEARCH_KEY, fedSearch)
// Tabs only ever see the projects of the selected collaborative spaces.
provide(PROJECT_MILESTONES_KEY, collabFilter.filteredMilestones)
provide(COLLAB_FILTER_KEY, collabFilter)

async function onTabKeydown(event: KeyboardEvent) {
  const currentIndex = tabs.findIndex((tab) => tab.id === activeTab.value)
  let nextIndex = currentIndex

  if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % tabs.length
  else if (event.key === 'ArrowLeft') nextIndex = (currentIndex - 1 + tabs.length) % tabs.length
  else if (event.key === 'Home') nextIndex = 0
  else if (event.key === 'End') nextIndex = tabs.length - 1
  else return

  event.preventDefault()
  const nextTab = tabs[nextIndex]!
  activeTab.value = nextTab.id
  await nextTick()
  document.getElementById(`tab-${nextTab.id}`)?.focus()
}
</script>

<template>
  <div class="app-layout">
    <header class="app-header">
      <div class="header-inner">
        <div class="brand">
          <span class="brand-mark" aria-hidden="true">
            <i class="mdi mdi-factory"></i>
          </span>
          <h1 class="brand-name">Project Tracker</h1>
        </div>

        <nav class="tab-nav" role="tablist" aria-label="Dashboard views" @keydown="onTabKeydown">
          <button
            v-for="tab in tabs"
            :id="`tab-${tab.id}`"
            :key="tab.id"
            type="button"
            role="tab"
            :class="['tab-btn', { active: activeTab === tab.id }]"
            :aria-selected="activeTab === tab.id"
            aria-controls="tab-panel"
            :tabindex="activeTab === tab.id ? 0 : -1"
            @click="activeTab = tab.id"
          >
            <i :class="['mdi', tab.icon]" aria-hidden="true"></i>
            {{ tab.label }}
          </button>
        </nav>

        <div class="header-tools">
          <CollabSpaceFilter
            v-model="collabSelected"
            :options="collabOptions"
            :active="activeSelection"
            :loading="fedSearch.loading.value"
          />
        </div>
      </div>
    </header>

    <main id="tab-panel" class="app-main" role="tabpanel" :aria-labelledby="`tab-${activeTab}`">
      <ProjectsTab v-if="activeTab === 'projects'" />
      <TimelineTab v-else-if="activeTab === 'timeline'" />
      <EventStatusTab v-else-if="activeTab === 'event'" />
    </main>
  </div>
</template>

