import { getPlatform } from "@/config/platformUrls";
import { httpRequest } from "@/api/transport";

/**
 * Base class for 3DSpace calls. The 3DSpace URL is resolved at runtime
 * (see config/platformUrls.js); requests go through api/transport.js.
 *
 * Requests resolve with `{ status, data }`, or with the error (marked `isAxiosError`)
 * on failure: errors are returned, not thrown, so callers must inspect the result.
 */
class EnoviaApi {
  constructor(path, option) {
    this.path = path;
    this.option = option;
  }

  async get() {
    const headers = { ENO_CSRF_TOKEN: "", ...this.option?.headers };
    return httpRequest({
      method: "GET",
      url: `${getPlatform().spaceUrl}${this.path}`,
      headers,
    }).catch((err) => Object.assign(err, { isAxiosError: true }));
  }
}

export default EnoviaApi;
