import type { StatusKey } from '@/dashboard/types/project'
import type { ProjectTask } from '@/dashboard/composables/useProjectMilestones'

/** "TRUE"/"FALSE" API flags as boolean. */
export function isTrue(value: unknown): boolean {
  if (typeof value === 'boolean') return value
  return String(value ?? '').toUpperCase() === 'TRUE'
}

/** A task is done when its state is "Complete" or its status is "completed…" (e.g. "completedLate"). */
export function isTaskComplete(task: ProjectTask): boolean {
  const state = String(task.state ?? '').toLowerCase()
  const status = String(task.status ?? '').toLowerCase()
  return state === 'complete' || status.startsWith('completed')
}

/**
 * Status of a single task/milestone:
 *   open and "late"      → delayed
 *   completed late       → potential-delay
 *   anything else        → on-track
 */
export function classifyTask(task: ProjectTask): StatusKey {
  const isLate = String(task.status ?? '').toLowerCase().includes('late')
  if (!isLate) return 'on-track'
  return isTaskComplete(task) ? 'potential-delay' : 'delayed'
}

/** Project status from its milestones: the worst milestone status wins. */
export function projectStatusFromMilestones(milestones: ProjectTask[]): StatusKey {
  const statuses = milestones.map(classifyTask)
  if (statuses.includes('delayed')) return 'delayed'
  if (statuses.includes('potential-delay')) return 'potential-delay'
  return 'on-track'
}
