import type { InjectionKey } from 'vue'
import type { useFederatedSearch } from '@/dashboard/composables/useFederatedSearch'
import type { useProjectMilestones } from '@/dashboard/composables/useProjectMilestones'
import type { useCollabSpaceFilter } from '@/dashboard/composables/useCollabSpaceFilter'

export type FederatedSearchState = ReturnType<typeof useFederatedSearch>
export type ProjectMilestonesState = ReturnType<typeof useProjectMilestones>
export type CollabSpaceFilterState = ReturnType<typeof useCollabSpaceFilter>

/** Live Project Space search results, provided by DashboardApp. */
export const FED_SEARCH_KEY: InjectionKey<FederatedSearchState> = Symbol('fedSearch')

/**
 * Project details and milestones, provided by DashboardApp, already restricted to the
 * collaborative spaces selected in the header filter.
 */
export const PROJECT_MILESTONES_KEY: InjectionKey<ProjectMilestonesState> = Symbol('projectMilestones')

/** Collaborative space filter state (selection, options), provided by DashboardApp. */
export const COLLAB_FILTER_KEY: InjectionKey<CollabSpaceFilterState> = Symbol('collabFilter')
