import type { StatusLabel, StatusKey, Tone } from '@/dashboard/types/project'

interface StatusMeta {
  label: StatusLabel
  tone: Tone
  /** Lamp colour, kept in sync with --*-lamp tokens for canvas-based charts. */
  color: string
}

export const STATUS_META: Record<StatusKey, StatusMeta> = {
  'on-track': { label: 'On Track', tone: 'ok', color: '#1fb36b' },
  'potential-delay': { label: 'Potential Delay', tone: 'warn', color: '#f2ae00' },
  delayed: { label: 'Delayed', tone: 'bad', color: '#e5412d' },
}

const KEY_BY_LABEL = Object.fromEntries(
  Object.entries(STATUS_META).map(([key, meta]) => [meta.label, key as StatusKey]),
) as Record<string, StatusKey>

/** Converts a display status ("Potential Delay") to its key ("potential-delay"). */
export function toStatusKey(status: string): StatusKey | undefined {
  return KEY_BY_LABEL[status]
}

export function toneForStatus(status: string): Tone {
  const key = toStatusKey(status)
  return key ? STATUS_META[key].tone : 'neutral'
}

/** Chart colour for a status label, falling back to the colour supplied by the data. */
export function colorForStatus(status: string, fallback: string): string {
  const key = toStatusKey(status)
  return key ? STATUS_META[key].color : fallback
}
