<script setup lang="ts">
import type { MetricItem } from '@/dashboard/types/project'

defineProps<{
  items: MetricItem[]
  label: string
  /** Smaller figures and padding, for tabs where the table needs the room */
  dense?: boolean
}>()

const emit = defineEmits<{ select: [item: MetricItem] }>()

function onKey(event: KeyboardEvent, item: MetricItem) {
  if (!item.clickable) return
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault()
    emit('select', item)
  }
}
</script>

<template>
  <section :class="['strip', { dense }]" :aria-label="label">
    <dl class="strip-items">
      <div
        v-for="item in items"
        :key="item.key ?? item.label"
        :class="[
          'item',
          `tone-${item.tone ?? 'neutral'}`,
          { 'has-split': item.split, clickable: item.clickable },
        ]"
        :role="item.clickable ? 'button' : undefined"
        :tabindex="item.clickable ? 0 : undefined"
        :title="item.clickable ? `Show ${item.label.toLowerCase()} projects` : undefined"
        @click="item.clickable && emit('select', item)"
        @keydown="onKey($event, item)"
      >
        <dt class="item-label">
          <span v-if="item.tone && item.tone !== 'neutral'" class="lamp" aria-hidden="true"></span>
          {{ item.label }}
        </dt>
        <dd v-if="item.value" class="item-value">
          {{ item.value }}
        </dd>
        <dd v-if="item.note" class="item-note">{{ item.note }}</dd>
        <dd v-if="item.split" class="item-split">
          <div v-for="part in item.split" :key="part.label" class="split-cell">
            <span class="split-label">{{ part.label }}</span>
            <span class="split-value">
              {{ part.value }}<span v-if="part.of" class="item-of">{{ part.of }}</span>
            </span>
          </div>
        </dd>
      </div>
    </dl>
  </section>
</template>

<style scoped>
/* Cells draw their own right/bottom hairline; the negative margin plus
   overflow:hidden trims the outer edge, so any wrap count divides cleanly. */
.strip {
  flex-shrink: 0; /* never let a flex parent squash the strip and clip the cards */
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-panel);
}

.strip-items {
  display: flex;
  flex-wrap: nowrap;
  margin: 0 -1px -1px 0;
  overflow-x: auto;
  overflow-y: hidden;
}

/* Split cards (e.g. milestone Customer | Indo counts) keep a readable width;
   when there are many, the strip scrolls horizontally instead of squashing. */
.item.has-split {
  flex: 1.4 1 0;
  min-width: 11rem;
}

.item-split {
  display: grid;
  grid-auto-columns: 1fr;
  grid-auto-flow: column;
  margin: 0;
  border-top: 1px solid var(--line-soft);
}

.split-cell {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
  padding-top: var(--space-2);
}

.split-cell + .split-cell {
  padding-left: var(--space-3);
  border-left: 1px solid var(--line-soft);
}

.split-cell:first-child {
  padding-right: var(--space-3);
}

.split-label {
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--ink-500);
}

.split-value {
  font-size: 1.75rem;
  font-weight: 700;
  font-stretch: var(--stretch-display);
  line-height: 1;
  color: var(--ink-900);
}

.item {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 0;
  padding: var(--space-4) var(--space-5);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.item-label {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--ink-600);
}

.lamp {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
}

.item-value {
  margin: 0;
  font-size: var(--text-figure);
  font-weight: 700;
  font-stretch: var(--stretch-display);
  line-height: 1;
  letter-spacing: -0.01em;
  color: var(--ink-900);
}

.item-of {
  margin-left: 0.25rem;
  font-size: var(--text-md);
  font-weight: 500;
  color: var(--ink-400);
}

.item-note {
  margin: 0;
  font-size: var(--text-xs);
  color: var(--ink-500);
}

.item.clickable {
  cursor: pointer;
  transition: background-color 0.15s;
}

.item.clickable:hover {
  background: var(--surface-sunken);
}

.item.clickable:focus-visible {
  outline-offset: -2px;
}

/* Dense: same layout, tighter, for tabs where the table needs the height */
.dense .item {
  gap: var(--space-1);
  padding: var(--space-2) var(--space-4);
}

.dense .item-label {
  font-size: var(--text-xs);
}

.dense .item-value {
  font-size: 1.75rem;
}

.dense .split-value {
  font-size: 1.35rem;
}

.dense .split-cell {
  padding-top: var(--space-1);
}

.tone-ok .item-value {
  color: var(--ok);
}
.tone-warn .item-value {
  color: var(--warn);
}
.tone-bad .item-value {
  color: var(--bad);
}

.tone-ok .lamp {
  background: var(--ok-lamp);
}
.tone-warn .lamp {
  background: var(--warn-lamp);
}
.tone-bad .lamp {
  background: var(--bad-lamp);
}
</style>
