<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import type { CollabSpaceOption } from '@/dashboard/composables/useCollabSpaceFilter'

const props = defineProps<{
  options: CollabSpaceOption[]
  /** Selected spaces that still exist (empty = all) */
  active: string[]
  loading?: boolean
}>()

/** Selected collaborative spaces; empty means all. */
const selected = defineModel<string[]>({ required: true })

const open = ref(false)
const query = ref('')
const root = ref<HTMLElement | null>(null)
const searchInput = ref<HTMLInputElement | null>(null)

const totalProjects = computed(() => props.options.reduce((sum, o) => sum + o.count, 0))

const visibleOptions = computed(() => {
  const q = query.value.trim().toLowerCase()
  return q ? props.options.filter((o) => o.name.toLowerCase().includes(q)) : props.options
})

const buttonText = computed(() => {
  if (props.active.length === 0) return 'All collaborative spaces'
  if (props.active.length === 1) return props.active[0]
  return `${props.active.length} collaborative spaces`
})

const isChecked = (name: string) => props.active.length === 0 || props.active.includes(name)

function toggle(name: string) {
  // From "all", unticking one space selects every other space.
  const current = props.active.length ? [...props.active] : props.options.map((o) => o.name)
  const next = current.includes(name) ? current.filter((n) => n !== name) : [...current, name]
  // Every space ticked (or none) is the same as "all".
  selected.value = next.length === props.options.length || next.length === 0 ? [] : next
}

/** Ticks only this space. */
function only(name: string) {
  selected.value = props.options.length === 1 ? [] : [name]
}

function selectAll() {
  selected.value = []
}

function onDocumentPointer(event: PointerEvent) {
  if (root.value && !root.value.contains(event.target as Node)) open.value = false
}

function onKeydown(event: KeyboardEvent) {
  if (event.key === 'Escape' && open.value) {
    open.value = false
    root.value?.querySelector<HTMLButtonElement>('.filter-btn')?.focus()
  }
}

watch(open, async (isOpen) => {
  if (isOpen) {
    query.value = ''
    document.addEventListener('pointerdown', onDocumentPointer)
    await nextTick()
    searchInput.value?.focus()
  } else {
    document.removeEventListener('pointerdown', onDocumentPointer)
  }
})

onBeforeUnmount(() => document.removeEventListener('pointerdown', onDocumentPointer))
</script>

<template>
  <div ref="root" class="collab-filter" @keydown="onKeydown">
    <button
      type="button"
      :class="['filter-btn', { filtered: active.length > 0 }]"
      aria-haspopup="dialog"
      :aria-expanded="open"
      :disabled="loading && !options.length"
      @click="open = !open"
    >
      <i class="mdi mdi-account-group-outline" aria-hidden="true"></i>
      <span class="filter-text">{{ buttonText }}</span>
      <i :class="['mdi', open ? 'mdi-chevron-up' : 'mdi-chevron-down']" aria-hidden="true"></i>
    </button>

    <div v-if="open" class="filter-pop" role="dialog" aria-label="Filter by collaborative space">
      <div class="pop-head">
        <span class="pop-title">Collaborative spaces</span>
        <button type="button" class="link-btn" :disabled="active.length === 0" @click="selectAll">
          Select all
        </button>
      </div>

      <div v-if="options.length > 6" class="pop-search">
        <i class="mdi mdi-magnify" aria-hidden="true"></i>
        <input
          ref="searchInput"
          v-model="query"
          type="search"
          placeholder="Search spaces"
          aria-label="Search collaborative spaces"
        />
      </div>

      <ul class="pop-list">
        <li v-for="option in visibleOptions" :key="option.name" class="pop-item">
          <label class="pop-check">
            <input type="checkbox" :checked="isChecked(option.name)" @change="toggle(option.name)" />
            <span class="pop-name" :title="option.name">{{ option.name }}</span>
            <span class="pop-count">{{ option.count }}</span>
          </label>
          <button type="button" class="only-btn" @click="only(option.name)">Only</button>
        </li>
        <li v-if="!visibleOptions.length" class="pop-empty">No matching spaces</li>
      </ul>

      <div class="pop-foot">
        {{ active.length ? active.length : options.length }} of {{ options.length }} spaces ·
        {{ totalProjects }} projects in total
      </div>
    </div>
  </div>
</template>

