import { createApp } from "vue";
import { initWidget } from "@/config/widgetConfig";
import App from "@/App.vue";
import store from "@/store";
import vuetify from "@/plugins/vuetify";
import initApp from "@/utility/initApp";
import "@/dashboard/assets/styles/main.css";

/* global __BUILD_TIME__ */
console.info(`[DashboardWidget] build ${__BUILD_TIME__}`);

initWidget(async (widget) => {
  const app = createApp(App);

  app.use(vuetify).use(store).mount("#app");

  // Order-sensitive: service URLs first, then the security context, then the dashboard.
  try {
    await initApp.platformUrls(widget);
    await initApp.userCtxCollabspaces(widget);
    await initApp.widgetLoad();
  } catch (err) {
    initApp.fail(err);
  }

  widget.addEvent("onLoad", () => app);
});
