import { computed, ref, toValue, watch, type MaybeRefOrGetter } from 'vue'

export function usePagination<T>(items: MaybeRefOrGetter<T[]>, initialPageSize: number) {
  const currentPage = ref(1)
  const pageSize = ref(initialPageSize)

  const totalItems = computed(() => toValue(items).length)
  const totalPages = computed(() => Math.max(1, Math.ceil(totalItems.value / pageSize.value)))

  // Stay on a real page when the list shrinks (e.g. a filter) or the page size grows.
  watch(totalPages, (pages) => {
    if (currentPage.value > pages) currentPage.value = pages
  })
  watch(pageSize, () => {
    currentPage.value = 1
  })

  const pageItems = computed(() => {
    const start = (currentPage.value - 1) * pageSize.value
    return toValue(items).slice(start, start + pageSize.value)
  })

  /** 1-based index of the first item on the page (0 when empty). */
  const rangeStart = computed(() =>
    totalItems.value ? (currentPage.value - 1) * pageSize.value + 1 : 0,
  )
  const rangeEnd = computed(() => Math.min(totalItems.value, currentPage.value * pageSize.value))

  return { currentPage, pageSize, totalPages, totalItems, rangeStart, rangeEnd, pageItems }
}
