import { computed, type Ref } from 'vue'
import { STATUS_META } from '@/dashboard/constants/status'
import { formatDayLabel, formatMonthLabel, parseApiDate, shortMonth } from '@/dashboard/utils/date'
import { findMilestone, milestoneDate } from '@/dashboard/utils/milestones'
import { classifyTask, isTaskComplete, isTrue } from '@/dashboard/utils/projectStatus'
import type { StatusKey, Tone } from '@/dashboard/types/project'
import type { ProjectDetail, ProjectTask } from './useProjectMilestones'

interface SummaryMetric {
  value: string
  subtitle: string
}

interface StatusCount {
  /** Status this count is for */
  key: StatusKey
  label: string
  value: number
  color: string
}

export interface DashboardSummary {
  metrics: Record<
    'totalProjects' | 'onTrack' | 'potentialDelay' | 'delayed' | 'lateProjects' | 'avgProgress',
    SummaryMetric
  >
  statusMix: StatusCount[]
  massProduction: Array<{ month: string; value: number; monthStart: number }>
  topLevelTasks: StatusCount[]
  /** `points` holds each label's date (ms) */
  burnDown: { labels: string[]; planned: number[]; actual: number[]; points: number[] }
}

/** One project in the drill-down panel, with why it is listed. */
export interface DrilldownEntry {
  project: ProjectDetail
  /** Short reason shown next to the project, e.g. "MP 14 Aug '26" */
  note?: string
  /** Extra lines, e.g. the names of the late milestones */
  details?: string[]
}

/** Contents of the drill-down panel opened from a chart or metric. */
export interface Drilldown {
  title: string
  subtitle: string
  tone?: Tone
  entries: DrilldownEntry[]
}

const STATUS_ORDER: StatusKey[] = ['on-track', 'potential-delay', 'delayed']

/** Max points on the burn-down chart; longer ranges use multi-week steps. */
const MAX_BURN_DOWN_POINTS = 26
const DAY_MS = 24 * 60 * 60 * 1000

function countByStatus(statuses: StatusKey[]): StatusCount[] {
  return STATUS_ORDER.map((key) => ({
    key,
    label: STATUS_META[key].label as string,
    value: statuses.filter((s) => s === key).length,
    color: STATUS_META[key].color,
  }))
}

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

// ─── Mass production schedule ────────────────────────────────────────────────

/** The customer MP milestone ("MP CUSTOMER", or plain "MP"); projects without one are skipped. */
function massProductionMilestone(project: ProjectDetail): ProjectTask | undefined {
  return findMilestone(project, 'MP', 'CUSTOMER')
}

function massProductionDate(project: ProjectDetail): Date | null {
  const milestone = massProductionMilestone(project)
  return milestone ? milestoneDate(milestone) : null
}

function monthStartOf(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth(), 1).getTime()
}

function massProduction(projects: ProjectDetail[]) {
  const perMonth = new Map<number, number>()
  for (const project of projects) {
    const date = massProductionDate(project)
    if (!date) continue
    const monthStart = monthStartOf(date)
    perMonth.set(monthStart, (perMonth.get(monthStart) ?? 0) + 1)
  }
  return Array.from(perMonth.entries())
    .sort(([a], [b]) => a - b)
    .map(([monthStart, value]) => ({
      month: formatMonthLabel(new Date(monthStart)),
      value,
      monthStart,
    }))
}

// ─── Top level tasks / burn down ─────────────────────────────────────────────

/** Top-level work items (phases/tasks), excluding milestones and gates. */
function isTopLevelTask(task: ProjectTask): boolean {
  return !isTrue(task.isTypeMilestone) && !isTrue(task.isTypeGate)
}

/** Work tasks only: no phases/summary tasks, milestones or gates. */
function isWorkTask(task: ProjectTask): boolean {
  return !isTrue(task.isSummaryTask) && !isTrue(task.isTypeMilestone) && !isTrue(task.isTypeGate)
}

interface FinishDates {
  planned: Date | null
  actual: Date | null
}

function finishDates(task: ProjectTask): FinishDates {
  const planned = parseApiDate(task.dueDate)
  const actual = parseApiDate(task.actualFinishDate) ?? (isTaskComplete(task) ? planned : null)
  return { planned, actual }
}

/**
 * Whether a task is still open at `point`: by its actual finish for past points,
 * by its planned finish for future points (as drawn on the burn-down chart).
 */
function isOpenAt(dates: FinishDates, point: number, now: number): boolean {
  const finish = point <= now ? dates.actual : dates.planned
  return !finish || finish.getTime() > point
}

function burnDown(projects: ProjectDetail[]): DashboardSummary['burnDown'] {
  const tasks = projects.flatMap((p) => p.tasks.filter(isWorkTask))
  const dates = tasks.map(finishDates)

  const starts = tasks.map((t) => parseApiDate(t.estimatedStartDate)).filter((d): d is Date => !!d)
  // Run until the later of the last planned finish and the last actual finish.
  const ends = dates.flatMap((d) => [d.planned, d.actual]).filter((d): d is Date => !!d)
  if (!starts.length || !ends.length) return { labels: [], planned: [], actual: [], points: [] }

  const first = new Date(Math.min(...starts.map((d) => d.getTime())))
  const last = Math.max(...ends.map((d) => d.getTime()))
  const weeks = Math.max(1, Math.ceil((last - first.getTime()) / (7 * DAY_MS)))
  const stepDays = 7 * Math.ceil(weeks / MAX_BURN_DOWN_POINTS)
  const now = Date.now()

  const labels: string[] = []
  const planned: number[] = []
  const actual: (number | null)[] = []
  const points: number[] = []

  for (let t = first.getTime() + stepDays * DAY_MS; ; t += stepDays * DAY_MS) {
    const point = Math.min(t, last)
    const pointDate = new Date(point)
    points.push(point)
    labels.push(`${pointDate.getDate()} ${shortMonth(pointDate)}`)
    planned.push(dates.filter((d) => !d.planned || d.planned.getTime() > point).length)
    actual.push(
      point <= now ? dates.filter((d) => !d.actual || d.actual.getTime() > point).length : null,
    )
    if (t >= last) break
  }

  // Chart.js draws null as a gap: the actual line stops at today.
  return { labels, planned, actual: actual as number[], points }
}

// ─── Summary ─────────────────────────────────────────────────────────────────

function buildSummary(projects: ProjectDetail[]): DashboardSummary {
  const total = projects.length
  const statusMix = countByStatus(projects.map((p) => p.statusKey))
  const [onTrack, potentialDelay, delayed] = statusMix.map((s) => s.value)
  const late = potentialDelay + delayed
  const avgProgress = total
    ? projects.reduce((sum, p) => sum + (p.percentComplete ?? 0), 0) / total
    : 0
  const latePercent = total ? Math.round((late / total) * 100) : 0

  return {
    metrics: {
      totalProjects: { value: String(total), subtitle: 'from 3DEXPERIENCE' },
      onTrack: { value: String(onTrack), subtitle: 'no open risk' },
      potentialDelay: { value: String(potentialDelay), subtitle: 'watch list' },
      delayed: { value: String(delayed), subtitle: 'needs escalation' },
      lateProjects: { value: `${latePercent}%`, subtitle: `${late} of ${total}` },
      avgProgress: { value: `${Math.round(avgProgress)}%`, subtitle: 'across portfolio' },
    },
    statusMix,
    massProduction: massProduction(projects),
    // Milestones/gates can sit at the top level too (e.g. "PP0 INDO"); they are not tasks.
    topLevelTasks: countByStatus(
      projects.flatMap((p) => p.phases.filter(isTopLevelTask).map(classifyTask)),
    ),
    burnDown: burnDown(projects),
  }
}

// ─── Drill-down (chart click → side panel) ───────────────────────────────────

/** Late / completed-late milestone names of a project. */
function lateMilestoneNames(project: ProjectDetail): string[] {
  return project.milestones
    .filter((m) => classifyTask(m) !== 'on-track')
    .map((m) => {
      const date = milestoneDate(m)
      const state = classifyTask(m) === 'delayed' ? 'late' : 'completed late'
      return `${m.title ?? 'Milestone'}${date ? ` · ${formatDayLabel(date)}` : ''} (${state})`
    })
}

function statusEntry(project: ProjectDetail): DrilldownEntry {
  const mp = massProductionDate(project)
  return {
    project,
    note: mp ? `MP ${formatDayLabel(mp)}` : undefined,
    details: project.statusKey === 'on-track' ? undefined : lateMilestoneNames(project),
  }
}

/** Worst status first, then by name. */
function byUrgency(a: DrilldownEntry, b: DrilldownEntry): number {
  const rank = (s: StatusKey) => STATUS_ORDER.length - STATUS_ORDER.indexOf(s)
  return (
    rank(b.project.statusKey) - rank(a.project.statusKey) ||
    a.project.projectLabel.localeCompare(b.project.projectLabel)
  )
}

/** Projects-tab data from the loaded projects (all zero/empty until projects are loaded). */
export function useProjectSummary(projects: Ref<ProjectDetail[]>) {
  const hasData = computed(() => projects.value.length > 0)
  const summary = computed<DashboardSummary>(() => buildSummary(projects.value))

  /** Projects with one of the given statuses (all projects when `statuses` is empty). */
  function byStatus(statuses: StatusKey[], title: string, tone?: Tone): Drilldown {
    const entries = projects.value
      .filter((p) => !statuses.length || statuses.includes(p.statusKey))
      .map(statusEntry)
      .sort(byUrgency)
    return { title, subtitle: plural(entries.length, 'project'), tone, entries }
  }

  /** Projects whose customer MP milestone falls in the clicked month. */
  function byMassProductionMonth(index: number): Drilldown | null {
    const bucket = summary.value.massProduction[index]
    if (!bucket) return null
    const entries = projects.value
      .map((project) => ({ project, date: massProductionDate(project) }))
      .filter(({ date }) => date && monthStartOf(date) === bucket.monthStart)
      .sort((a, b) => a.date!.getTime() - b.date!.getTime())
      .map(({ project, date }) => ({ project, note: `MP ${formatDayLabel(date!)}` }))
    return {
      title: `Mass production · ${bucket.month}`,
      subtitle: `${plural(entries.length, 'project')} with the customer MP milestone this month`,
      entries,
    }
  }

  /** Projects with top-level tasks in the clicked status, listing those tasks. */
  function byTopLevelTaskStatus(status: StatusKey): Drilldown {
    const entries: DrilldownEntry[] = []
    let taskCount = 0
    for (const project of projects.value) {
      const tasks = project.phases.filter((t) => isTopLevelTask(t) && classifyTask(t) === status)
      if (!tasks.length) continue
      taskCount += tasks.length
      entries.push({
        project,
        note: plural(tasks.length, 'task'),
        details: tasks.map((t) => {
          const due = parseApiDate(t.dueDate)
          const pct = Math.round(parseFloat(String(t.percentComplete ?? 0)) || 0)
          return `${t.title ?? 'Task'} · ${pct}%${due ? ` · due ${formatDayLabel(due)}` : ''}`
        }),
      })
    }
    entries.sort((a, b) => (b.details?.length ?? 0) - (a.details?.length ?? 0))
    return {
      title: `Top level tasks · ${STATUS_META[status].label}`,
      subtitle: `${plural(taskCount, 'task')} in ${plural(entries.length, 'project')}`,
      tone: STATUS_META[status].tone,
      entries,
    }
  }

  /** Projects that still have open work tasks at the clicked burn-down point. */
  function byBurnDownPoint(index: number): Drilldown | null {
    const point = summary.value.burnDown.points[index]
    if (point === undefined) return null
    const now = Date.now()
    const isPast = point <= now
    const entries: DrilldownEntry[] = []
    let open = 0
    for (const project of projects.value) {
      const remaining = project.tasks
        .filter(isWorkTask)
        .filter((t) => isOpenAt(finishDates(t), point, now))
      if (!remaining.length) continue
      open += remaining.length
      entries.push({ project, note: `${remaining.length} open` })
    }
    entries.sort((a, b) => parseInt(b.note!, 10) - parseInt(a.note!, 10))
    return {
      title: `Burn down · ${formatDayLabel(new Date(point))}`,
      subtitle: `${plural(open, 'task')} ${isPast ? 'still open' : 'planned to be open'} in ${plural(entries.length, 'project')}`,
      entries,
    }
  }

  return {
    hasData,
    summary,
    byStatus,
    byMassProductionMonth,
    byTopLevelTaskStatus,
    byBurnDownPoint,
  }
}
